def _compute_qty_to_deliver(self):
    """Compute the visibility of the inventory widget."""
    for line in self:
        line.qty_to_deliver = line.product_uom_qty - line.qty_delivered
        if line.state in ('draft', 'sent', 'sale') and line.is_storable and line.product_uom_id and line.qty_to_deliver > 0:
            if line.state == 'sale' and all(m.state in ['done', 'cancel'] for m in line.move_ids):
                line.display_qty_widget = False
            else:
                line.display_qty_widget = True
        else:
            line.display_qty_widget = False

def _prepare_qty_delivered(self):
    delivered_qties = super()._prepare_qty_delivered()
    for line in self:  # TODO: maybe one day, this should be done in SQL for performance sake
        if line.qty_delivered_method == 'stock_move':
            qty = 0.
            if line.order_id.sudo().warehouse_id.company_id != self.order_id.company_id:
                # If the selected warehouse belongs to another company, need to fetch their moves regardless.
                line = line.sudo()
            outgoing_moves, incoming_moves = line._get_outgoing_incoming_moves()
            for move in outgoing_moves:
                if move.state != 'done':
                    continue
                qty += move.uom_id._compute_quantity(move.quantity, line.product_uom_id, rounding_method='HALF-UP')
            for move in incoming_moves:
                # An unlinked move coming from a customer is still a real return, only skip unlinked non-returns (dropship receipts).
                if move.state != 'done' or (
                    not move.origin_returned_move_id
                    and not move.location_id._is_outgoing()
                    and line.product_uom_qty > 0
                    and not move.picking_id.return_id
                ):
                    continue
                qty -= move.uom_id._compute_quantity(move.quantity, line.product_uom_id, rounding_method='HALF-UP')

            delivered_qties[line] += qty
    return delivered_qties

def _update_line_quantity(self, values):
    precision = self.env['decimal.precision'].precision_get('Product Unit')
    line_products = self.filtered(lambda l: l.product_id.type == 'consu')
    if line_products.mapped('qty_delivered') and float_compare(values['product_uom_qty'], max(line_products.mapped('qty_delivered')), precision_digits=precision) == -1:
        raise UserError(_('The ordered quantity of a sale order line cannot be decreased below the amount already delivered. Instead, create a return in your inventory.'))
    super(SaleOrderLine, self)._update_line_quantity(values)

def _get_capacity(self, product, unit, default_capacity=1):
    capacity = self.capacity_ids.sorted(lambda c: (
        not (c.product_id == product and c.uom_id == product.uom_id),
        not (not c.product_id and c.uom_id == unit),
        not (not c.product_id and c.uom_id == product.uom_id),
    ))[:1]
    if capacity and capacity.product_id in [product, self.env['product.product']] and capacity.uom_id in [product.uom_id, unit]:
        if float_is_zero(capacity.capacity, 0):
            return (default_capacity, capacity.time_start, capacity.time_stop)
        return (capacity.uom_id._compute_quantity(capacity.capacity, unit), capacity.time_start, capacity.time_stop)
    return (default_capacity, self.time_start, self.time_stop)

def _compute_uom_id(self):
    for capacity in self:
        capacity.uom_id = capacity.product_id.uom_id or self.env.ref('uom.product_uom_unit')

def _check_stock_quantity(cls, sales):
    for sale in sales:
        sale.check_stock_quantity()

def _stock_quantity_next_supply_date(cls, product):
    pool = Pool()
    try:
        PurchaseRequest = pool.get('purchase.request')
    except KeyError:
        PurchaseRequest = None

    if (getattr(PurchaseRequest, 'get_supply_dates', None)
            and product.purchasable):
        return PurchaseRequest.get_supply_dates(product)[0]
    else:
        # TODO compute supply date for production
        return datetime.date.max

def get_supply_state(self, name):
    state = super().get_supply_state(name)
    if self.productions:
        states = {p.state for p in self.productions}
        if states <= {'running', 'done', 'cancelled'}:
            if states == {'cancelled'}:
                state = 'cancelled'
            else:
                state = 'supplied'
        else:
            state = 'requested'
    return state

@Override
public BigDecimal computeFutureQty(StockLocationLine stockLocationLine) throws AxelorException {
  // future quantity = current quantity - planned outgoing + planned incoming
  BigDecimal futureQty =
      stockLocationLine.getCurrentQty() != null
          ? stockLocationLine.getCurrentQty()
          : BigDecimal.ZERO;

  Product product = stockLocationLine.getProduct();

  if (stockLocationLine.getUnit() == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.LOCATION_LINE_MISSING_UNIT),
        stockLocationLine.getStockLocation().getName(),
        product.getFullName());
  }

  boolean isDetailsStockLocationLine = stockLocationLine.getDetailsStockLocation() != null;
  Long stockLocationId =
      isDetailsStockLocationLine
          ? stockLocationLine.getDetailsStockLocation().getId()
          : stockLocationLine.getStockLocation().getId();
  Long trackingNumberId =
      isDetailsStockLocationLine && stockLocationLine.getTrackingNumber() != null
          ? stockLocationLine.getTrackingNumber().getId()
          : null;

  StringBuilder jpql = new StringBuilder();
  jpql.append(
      "SELECT new com.axelor.apps.stock.utils.StockLocationLineQtyView("
          + " self.unit, "
          + " SUM(CASE WHEN self.toStockLocation.id = :stockLocationId THEN COALESCE(self.qty, 0) ELSE 0 END), "
          + " SUM(CASE WHEN self.fromStockLocation.id = :stockLocationId THEN COALESCE(self.qty, 0) ELSE 0 END) "
          + ") "
          + " FROM StockMoveLine self "
          + " WHERE (self.stockMove.archived IS NULL OR self.archived IS FALSE) "
          + " AND self.stockMove.statusSelect = :planned "
          + " AND self.product.id = :productId "
          + " AND (self.toStockLocation.id = :stockLocationId OR self.fromStockLocation.id = :stockLocationId) ");
  if (isDetailsStockLocationLine) {
    jpql.append(" AND self.trackingNumber.id = :trackingNumberId ");
  }
  jpql.append(" GROUP BY self.unit");

  var query =
      JPA.em()
          .createQuery(jpql.toString(), StockLocationLineQtyView.class)
          .setParameter("planned", StockMoveRepository.STATUS_PLANNED)
          .setParameter("productId", product.getId())
          .setParameter("stockLocationId", stockLocationId);
  if (isDetailsStockLocationLine) {
    query.setParameter("trackingNumberId", trackingNumberId);
  }
  query.setFlushMode(FlushModeType.COMMIT);
  List<StockLocationLineQtyView> aggregates = query.getResultList();

  for (StockLocationLineQtyView agg : aggregates) {
    Unit aggUnit = agg.getUnit();
    BigDecimal incoming = agg.getIncoming() != null ? agg.getIncoming() : BigDecimal.ZERO;
    BigDecimal outgoing = agg.getOutgoing() != null ? agg.getOutgoing() : BigDecimal.ZERO;

    if (incoming.compareTo(BigDecimal.ZERO) != 0) {
      BigDecimal incConverted =
          unitConversionService.convertWithAutoFlushFalse(
              aggUnit, stockLocationLine.getUnit(), incoming, incoming.scale(), product);
      futureQty = futureQty.add(incConverted);
    }

    if (outgoing.compareTo(BigDecimal.ZERO) != 0) {
      BigDecimal outConverted =
          unitConversionService.convertWithAutoFlushFalse(
              aggUnit, stockLocationLine.getUnit(), outgoing, outgoing.scale(), product);
      futureQty = futureQty.subtract(outConverted);
    }
  }

  return futureQty;
}

@Override
public void computeMarginSaleOrder(SaleOrder saleOrder) {
  BigDecimal accountedRevenue = BigDecimal.ZERO;
  BigDecimal totalCostPrice = BigDecimal.ZERO;
  BigDecimal totalGrossMargin = BigDecimal.ZERO;

  if (saleOrder.getSaleOrderLineList() != null && !saleOrder.getSaleOrderLineList().isEmpty()) {
    boolean considerZeroCost = appSaleService.getAppSale().getConsiderZeroCost();
    for (SaleOrderLine saleOrderLine : saleOrder.getSaleOrderLineList()) {
      if (saleOrderLine.getProduct() == null
          || (saleOrderLine.getExTaxTotal().compareTo(BigDecimal.ZERO) == 0
              && !considerZeroCost)) {
        continue;
      }
      totalGrossMargin = totalGrossMargin.add(saleOrderLine.getSubTotalGrossMargin());
      totalCostPrice = totalCostPrice.add(saleOrderLine.getSubTotalCostPrice());
      accountedRevenue = accountedRevenue.add(saleOrderLine.getCompanyExTaxTotal());
    }
  }

  setSaleOrderMarginInfo(
      saleOrder,
      accountedRevenue,
      totalCostPrice,
      totalGrossMargin,
      computeRate(accountedRevenue, totalGrossMargin),
      computeRate(totalCostPrice, totalGrossMargin));
}

protected void setSaleOrderMarginInfo(
    SaleOrder saleOrder,
    BigDecimal accountedRevenue,
    BigDecimal totalCostPrice,
    BigDecimal totalGrossMargin,
    BigDecimal marginRate,
    BigDecimal markup) {
  saleOrder.setAccountedRevenue(accountedRevenue);
  saleOrder.setTotalCostPrice(totalCostPrice);
  saleOrder.setTotalGrossMargin(totalGrossMargin);
  saleOrder.setMarginRate(marginRate);
  saleOrder.setMarkup(markup);
}

protected MrpLine setMrpLineQty(MrpLine mrpLine, Product product, StockLocation stockLocation) {

  StockRules stockRules =
      stockRulesService.getStockRules(
          product,
          stockLocation,
          StockRulesRepository.TYPE_FUTURE,
          StockRulesRepository.USE_CASE_USED_FOR_MRP);

  if (stockRules != null) {
    mrpLine.setMinQty(stockRules.getMinQty());
    mrpLine.setIdealQty(stockRules.getIdealQty());
    mrpLine.setReOrderQty(stockRules.getReOrderQty());
  }
  return mrpLine;
}

@Override
public void computeMarginSaleOrder(SaleOrder saleOrder) {
  super.computeMarginSaleOrder(saleOrder);
  saleOrder.setTotalCostPrice(saleOrder.getTotalCostPrice().add(saleOrder.getShippingCost()));
}

def get_projected_qty(item_code, warehouse):
	# record-level read on the item, as get_item_details() in this file already does. Nothing in the
	# tree calls this, so no caller's roles constrain the choice.
	frappe.has_permission("Item", doc=item_code, throw=True)

	return {
		"projected_qty": frappe.db.get_value(
			"Bin", {"item_code": item_code, "warehouse": warehouse}, "projected_qty"
		)
	}

def get_batch_qty(batch_no, warehouse, item_code):
	from erpnext.stock.doctype.batch import batch

	if batch_no:
		return {"actual_batch_qty": batch.get_batch_qty(batch_no, warehouse)}

def update_work_order_qty(self):
	"""Update **Manufactured Qty** and **Material Transferred for Qty** in Work Order
	based on Stock Entry"""

	if self.track_semi_finished_goods:
		return

	# Lock the plan row before any Work Order quantity update takes a row lock.
	self.set_process_loss_qty()
	overproduction_percentage = flt(
		frappe.db.get_single_value("Manufacturing Settings", "overproduction_percentage_for_work_order")
	)
	transfer_extra_percentage = flt(
		frappe.db.get_single_value("Manufacturing Settings", "transfer_extra_materials_percentage")
	)

	for purpose, fieldname in (
		("Manufacture", "produced_qty"),
		("Material Transfer for Manufacture", "material_transferred_for_manufacturing"),
		("Material Transfer for Manufacture", "additional_transferred_qty"),
	):
		if (
			purpose == "Material Transfer for Manufacture"
			and self.operations
			and self.transfer_material_against == "Job Card"
		):
			continue

		qty = self.get_transferred_or_manufactured_qty(purpose, fieldname)

		allowance_percentage = overproduction_percentage
		if purpose == "Material Transfer for Manufacture":
			allowance_percentage = transfer_extra_percentage or overproduction_percentage

		completed_qty = self.qty + (allowance_percentage / 100 * self.qty)
		qty_to_validate = qty + flt(self.process_loss_qty) if purpose == "Manufacture" else qty
		precision = self.precision(fieldname)
		if flt(qty_to_validate, precision) > flt(completed_qty, precision):
			frappe.throw(
				_("{0} ({1}) cannot be greater than planned quantity ({2}) in Work Order {3}").format(
					_("Manufactured Qty (including Process Loss)")
					if purpose == "Manufacture"
					else _(self.meta.get_label(fieldname)),
					flt(qty_to_validate, precision),
					completed_qty,
					self.name,
				),
				StockOverProductionError,
			)

		if purpose == "Manufacture":
			self.validate_produced_qty_covers_disassembly(qty, precision)

		self.db_set(fieldname, qty)
		if purpose == "Manufacture" and self.production_plan:
			ProductionPlanWorkOrderQuantities(self.production_plan).validate_work_order(
				self, process_loss_qty=self.process_loss_qty
			)

		from erpnext.selling.doctype.sales_order.sales_order import update_produced_qty_in_so_item

		if self.sales_order and self.sales_order_item and not self.production_plan_sub_assembly_item:
			update_produced_qty_in_so_item(self.sales_order, self.sales_order_item)

	if self.production_plan:
		self.set_produced_qty_for_sub_assembly_item()
		self.update_production_plan_status()

	if self.additional_transferred_qty:
		self.validate_additional_transferred_qty()

def validate_additional_transferred_qty(self):
	transfer_extra_materials_percentage = frappe.db.get_single_value(
		"Manufacturing Settings", "transfer_extra_materials_percentage"
	)

	allowed_qty = flt(self.qty) + flt(flt(self.qty) * flt(transfer_extra_materials_percentage) / 100)

	actual_qty = flt(self.material_transferred_for_manufacturing) + flt(self.additional_transferred_qty)

	precision = frappe.get_precision("Work Order", "qty")
	if flt(allowed_qty - actual_qty, precision) < 0:
		frappe.throw(
			_(
				"""Additional Transferred Qty {0}
				cannot be greater than {1}.
				To fix this, increase the percentage value
				of the field 'Transfer Extra Raw Materials to WIP'
				in Manufacturing Settings."""
			).format(actual_qty, allowed_qty),
		)

def validate_produced_qty_covers_disassembly(self, produced_qty, precision):
	if flt(produced_qty, precision) >= flt(self.disassembled_qty, precision):
		return

	frappe.throw(
		_(
			"Manufactured Qty ({0}) cannot be less than the Disassembled Qty ({1}) of Work Order {2}. Cancel the disassembly first."
		).format(flt(produced_qty, precision), flt(self.disassembled_qty, precision), self.name)
	)

def update_disassembled_qty(self, qty, is_cancel=False):
	precision = self.precision("disassembled_qty")
	if is_cancel:
		self.disassembled_qty = max(0, flt(self.disassembled_qty - qty, precision))
	else:
		if self.docstatus == 1:
			self.disassembled_qty = flt(self.disassembled_qty + qty, precision)

	if not is_cancel and self.disassembled_qty > self.produced_qty:
		frappe.throw(_("Cannot disassemble more than produced quantity."))

	self.db_set("disassembled_qty", self.disassembled_qty)

def get_transferred_or_manufactured_qty(self, purpose, fieldname):
	parent = frappe.qb.DocType("Stock Entry")

	query = frappe.qb.from_(parent).where(
		(parent.work_order == self.name)
		& (parent.docstatus == 1)
		& (parent.purpose == purpose)
		& (parent.is_additional_transfer_entry == cint(fieldname == "additional_transferred_qty"))
	)

	if purpose == "Manufacture":
		child = frappe.qb.DocType("Stock Entry Detail")
		query = (
			query.join(child)
			.on(parent.name == child.parent)
			.select(Sum(child.transfer_qty))
			.where(child.is_finished_item == 1)
		)
	else:
		query = query.select(Sum(parent.fg_completed_qty))

	return flt(query.run()[0][0])

def set_process_loss_qty(self):
	quantities = None
	if self.docstatus == 1 and self.production_plan:
		quantities = ProductionPlanWorkOrderQuantities(self.production_plan)
		quantities.lock_plan_row(self)

	process_loss_qty = self._process_loss_qty()
	if quantities:
		previous_loss_qty = frappe.db.get_value(
			"Work Order", self.name, "process_loss_qty", for_update=True
		)
		if process_loss_qty < flt(previous_loss_qty):
			# Replacement Work Orders may have consumed the recorded loss.
			quantities.validate_work_order(self, process_loss_qty=process_loss_qty)
	self.db_set("process_loss_qty", process_loss_qty)

def _process_loss_qty(self):
	if self.track_semi_finished_goods:
		return flt(sum(flt(row.process_loss_qty) for row in self.operations))

	table = frappe.qb.DocType("Stock Entry")
	process_loss_qty = (
		frappe.qb.from_(table)
		.select(Sum(table.process_loss_qty))
		.where(
			(table.work_order == self.name) & (table.purpose == "Manufacture") & (table.docstatus == 1)
		)
	).run()[0][0]

	return flt(process_loss_qty)

def set_qty_change(self):
	"""Excess received qty to move into this Work Order's reservation on submit."""
	if scio_item_name := self.get("subcontracting_inward_order_item"):
		self.qty_change = frappe._dict()

		data = frappe.get_all(
			"Subcontracting Inward Order Received Item",
			{"reference_name": scio_item_name, "docstatus": 1, "is_customer_provided_item": 1},
			["rm_item_code", "required_qty as bom_qty", "work_order_qty", "received_qty"],
		)
		for d in data:
			wo_item = next(
				(
					wo_item
					for wo_item in self.get("required_items")
					if wo_item.item_code == d.rm_item_code
				),
				None,
			)

			if wo_item and d.work_order_qty == d.bom_qty and d.received_qty > d.bom_qty:
				self.qty_change[wo_item.name] = d.received_qty - d.bom_qty

def update_planned_qty(self):
	if self.track_semi_finished_goods:
		return

	update_bin_qty(
		self.production_item,
		self.fg_warehouse,
		{"planned_qty": get_planned_qty(self.production_item, self.fg_warehouse)},
	)

	if self.material_request:
		mr_obj = frappe.get_doc("Material Request", self.material_request)
		mr_obj.update_requested_qty([self.material_request_item])

def update_ordered_qty(self):
	if self.production_plan and (self.production_plan_item or self.production_plan_sub_assembly_item):
		table = frappe.qb.DocType("Work Order")

		query = (
			frappe.qb.from_(table)
			.select(Sum(table.qty))
			.where((table.production_plan == self.production_plan) & (table.docstatus == 1))
		)

		if self.production_plan_item:
			query = query.where(table.production_plan_item == self.production_plan_item)
		elif self.production_plan_sub_assembly_item:
			query = query.where(
				table.production_plan_sub_assembly_item == self.production_plan_sub_assembly_item
			)

		query = query.run()
		qty = flt(query[0][0]) if query else 0

		if self.production_plan_item:
			frappe.db.set_value("Production Plan Item", self.production_plan_item, "ordered_qty", qty)
		elif self.production_plan_sub_assembly_item:
			frappe.db.set_value(
				"Production Plan Sub Assembly Item",
				self.production_plan_sub_assembly_item,
				"ordered_qty",
				qty,
			)

		doc = frappe.get_doc("Production Plan", self.production_plan)
		doc.flags.ignore_permissions = True
		doc.update_status_and_bin_qty()
		doc.update_bin_qty({d.item_code for d in self.required_items})

def get_work_order_qty_against_sales_order(self):
	wo = frappe.qb.DocType("Work Order")
	query = (
		frappe.qb.from_(wo)
		.select(Sum(qty_against_sales_order(wo, wo.qty)))
		.where((wo.sales_order == self.sales_order) & (wo.docstatus == 1))
	)
	if self.product_bundle_item:
		query = query.where(wo.product_bundle_item == self.product_bundle_item)
	else:
		query = query.where(
			(wo.production_item == self.production_item) & (wo.sales_order_item == self.sales_order_item)
		)

	return query.run(as_list=1)

def get_ordered_qty_of_plan_item(self):
	work_order = frappe.qb.DocType("Work Order")
	return flt(
		(
			frappe.qb.from_(work_order)
			.select(Sum(work_order.qty))
			.where(
				(work_order.production_plan_item == self.production_plan_item)
				& (work_order.docstatus == 1)
				& (work_order.status != "Closed")
			)
		).run()[0][0]
	)

def update_completed_qty_in_material_request(self):
	if self.material_request and self.material_request_item:
		frappe.get_doc("Material Request", self.material_request).update_completed_qty(
			[self.material_request_item]
		)

def validate_qty(self):
	if self.qty <= 0:
		frappe.throw(_("Quantity to Manufacture must be greater than 0."))

	if flt(self.batch_size) < 0:
		frappe.throw(_("Batch Size cannot be negative."))

	if (
		self.stock_uom
		and frappe.get_cached_value("UOM", self.stock_uom, "must_be_whole_number")
		and abs(cint(self.qty) - flt(self.qty, self.precision("qty"))) > 0.0000001
	):
		frappe.throw(
			_(
				"Qty To Manufacture ({0}) cannot be a fraction for the UOM {2}. To allow this, disable '{1}' in the UOM {2}."
			).format(
				flt(self.qty, self.precision("qty")),
				frappe.bold(_("Must be Whole Number")),
				frappe.bold(self.stock_uom),
			),
		)

	if self.subcontracting_inward_order and self.qty > self.max_producible_qty:
		frappe.msgprint(
			_(
				"Warning: Quantity exceeds maximum producible quantity based on quantity of raw materials received through the Subcontracting Inward Order {0}."
			).format(get_link_to_form("Subcontracting Inward Order", self.subcontracting_inward_order)),
			alert=True,
			indicator="orange",
		)

def update_reserved_qty_for_production(self, items=None):
	"""update reserved_qty_for_production in bins"""
	for d in self.required_items:
		if d.source_warehouse:
			stock_bin = get_bin(d.item_code, d.source_warehouse)
			stock_bin.update_reserved_qty_for_production()

def set_available_qty(self):
	for d in self.get("required_items"):
		if d.source_warehouse:
			d.available_qty_at_source_warehouse = get_latest_stock_qty(d.item_code, d.source_warehouse)

		if self.wip_warehouse:
			d.available_qty_at_wip_warehouse = get_latest_stock_qty(d.item_code, self.wip_warehouse)

def update_transferred_qty_for_required_items(self):
	if self.skip_transfer:
		return

	transferred_by_key = self._material_transfer_qty_by_item_warehouse_and_operation()
	transferred_items = frappe._dict()
	for (item_code, _warehouse, _operation_row_id, _operation), qty in transferred_by_key.items():
		transferred_items[item_code] = flt(transferred_items.get(item_code)) + qty

	row_wise_serial_batch = frappe._dict({})
	if self.reserve_stock:
		row_wise_serial_batch = get_row_wise_serial_batch(self.name)

	transferred_by_row = distribute_transfers_over_rows(self.required_items, transferred_by_key)
	for row in self.required_items:
		transferred_qty = transferred_by_row[row.name]
		row.db_set("transferred_qty", transferred_qty, update_modified=False)
		if self.reserve_stock:
			self.update_qty_in_stock_reservation(row, transferred_qty, row_wise_serial_batch)

	self.recompute_material_transferred_for_manufacturing(transferred_items)

def update_qty_in_stock_reservation(self, row, transferred_qty, row_wise_serial_batch):
	filters = {
		"voucher_no": self.name,
		"item_code": row.item_code,
		"voucher_detail_no": row.name,
		"warehouse": row.source_warehouse,
	}
	names = frappe.get_all(
		"Stock Reservation Entry",
		filters={**filters, "status": ("not in", ["Closed", "Cancelled", "Completed"])},
		pluck="name",
	)
	if self.status == "Closed":
		names += frappe.get_all(
			"Stock Reservation Entry",
			filters={**filters, "docstatus": 2, "transferred_qty": (">", 0)},
			pluck="name",
			order_by="creation",
		)

	if names:
		for name in names:
			doc = frappe.get_doc("Stock Reservation Entry", name)
			qty_to_update = 0.0
			if transferred_qty < 0:
				continue

			qty_to_update = min(flt(transferred_qty), flt(doc.reserved_qty - doc.consumed_qty))
			transferred_qty = flt(transferred_qty) - qty_to_update

			if qty_to_update < 0:
				continue

			if doc.docstatus == 2:
				doc.db_set("transferred_qty", flt(qty_to_update), update_modified=False)
				doc.release_reversed_usage("transferred_qty", row_wise_serial_batch)
				continue

			if (doc.has_batch_no or doc.has_serial_no) and doc.reservation_based_on == "Serial and Batch":
				doc.consume_serial_batch_for_material_transfer(row_wise_serial_batch)
				qty_to_update = doc.matched_serial_batch_qty

			doc.db_set("transferred_qty", flt(qty_to_update), update_modified=False)
			if doc.transferred_qty >= doc.reserved_qty:
				doc.db_set("status", "Closed", update_modified=False)

			doc.update_status()
			doc.update_reserved_stock_in_bin()
			doc.update_reserved_qty_in_voucher()

def update_returned_qty(self):
	returned_by_row = distribute_over_rows(
		self.required_items, self._material_transfer_qty_by_item(is_return=1)
	)
	for row in self.required_items:
		row.db_set("returned_qty", returned_by_row[row.name], update_modified=False)

def update_consumed_qty_in_stock_reservation(self, item, consumed_qty, wip_warehouse):
	filters = {
		"voucher_no": self.name,
		"item_code": item.item_code,
		"voucher_detail_no": item.name,
		"warehouse": wip_warehouse,
		"docstatus": 1,
	}
	or_filters = None
	if self.status == "Closed":
		filters["docstatus"] = ("in", [1, 2])
		or_filters = {"docstatus": 1, "consumed_qty": (">", 0)}

	if not self.skip_transfer:
		filters["from_voucher_no"] = ("is", "set")

	row_wise_serial_batch = get_row_wise_serial_batch(self.name, CONSUMPTION_PURPOSES)

	if names := frappe.get_all(
		"Stock Reservation Entry",
		filters=filters,
		or_filters=or_filters,
		pluck="name",
		order_by="creation",
	):
		for name in names:
			if consumed_qty < 0:
				consumed_qty = 0

			doc = frappe.get_doc("Stock Reservation Entry", name)
			reserved_qty = doc.reserved_qty
			qty_to_update = consumed_qty if consumed_qty < reserved_qty else reserved_qty
			if qty_to_update >= 0:
				doc.db_set("consumed_qty", flt(qty_to_update), update_modified=False)
				consumed_qty -= qty_to_update

			if doc.docstatus == 2:
				doc.release_reversed_usage("consumed_qty", row_wise_serial_batch)
				continue

			if (doc.has_batch_no or doc.has_serial_no) and doc.reservation_based_on == "Serial and Batch":
				doc.consume_serial_batch_for_material_transfer(row_wise_serial_batch)
				doc.db_set("consumed_qty", doc.matched_serial_batch_qty, update_modified=False)

			doc.update_status()
			doc.update_reserved_stock_in_bin()
			doc.update_reserved_qty_in_voucher()

def validate_reserved_qty(self):
	sre_details = get_sre_details(self.name)
	for item in self.required_items:
		if details := sre_details.get(item.name):
			if details.reserved_qty < details.consumed_qty:
				frappe.throw(
					_("Consumed Qty cannot be greater than Reserved Qty for item {0}").format(
						details.consumed_qty, details.reserved_qty, item.item_code
					)
				)

def set_reserved_qty_for_wip_and_fg(self, stock_entry):
	if stock_entry.is_return:
		return

	items = frappe._dict()

	stock_entry.reload()
	if stock_entry.purpose == "Manufacture" and (
		self.sales_order
		or self.production_plan_sub_assembly_item
		or self.subcontracting_inward_order
		or stock_entry.job_card
	):
		items = self.get_finished_goods_for_reservation(stock_entry)
	elif stock_entry.purpose == "Material Transfer for Manufacture":
		items = self.get_list_of_materials_for_reservation(stock_entry)

	if not items:
		return

	item_list = list(items.values())
	reserve_stock_for_work_order(self, item_list, is_transfer=False, notify=True)

def cancel_reserved_qty_for_wip_and_fg(self, ste_doc):
	for row in ste_doc.items:
		sre_list = frappe.get_all(
			"Stock Reservation Entry",
			filters={
				"from_voucher_no": ste_doc.name,
				"from_voucher_detail_no": row.name,
				"docstatus": 1,
			},
			pluck="name",
		)

		if sre_list:
			unreserve_stock_for_work_order(self, sre_list)

def _subcontract_transferred_qty_by_item(self):
	"""Qty sent to subcontractors for this Work Order, keyed by (item_code, source warehouse).

	The transfer Stock Entries are linked to the Work Order through its subcontracted Job Cards
	(Job Card -> Subcontracting Order / Purchase Order -> Send to Subcontractor entry), since the
	entry itself does not retain ``work_order``. Only submitted (docstatus 1) entries contribute,
	so a cancelled transfer drops out and the reservation is restored on the next recompute.
	"""
	job_cards = frappe.get_all(
		"Job Card", filters={"work_order": self.name, "is_subcontracted": 1}, pluck="name"
	)
	if not job_cards:
		return {}

	sco_names = frappe.get_all(
		"Subcontracting Order Item", filters={"job_card": ["in", job_cards]}, pluck="parent"
	)
	po_names = frappe.get_all(
		"Purchase Order Item", filters={"job_card": ["in", job_cards]}, pluck="parent"
	)
	if not sco_names and not po_names:
		return {}

	ste = frappe.qb.DocType("Stock Entry")
	ste_child = frappe.qb.DocType("Stock Entry Detail")

	link = None
	if sco_names:
		link = ste.subcontracting_order.isin(list(set(sco_names)))
	if po_names:
		po_link = ste.purchase_order.isin(list(set(po_names)))
		link = po_link if link is None else (link | po_link)

	rows = (
		frappe.qb.from_(ste)
		.inner_join(ste_child)
		.on(ste_child.parent == ste.name)
		.select(ste_child.item_code, ste_child.s_warehouse, fn.Sum(ste_child.transfer_qty).as_("qty"))
		.where(
			(ste.docstatus == 1)
			& (ste.purpose == "Send to Subcontractor")
			& (ste_child.s_warehouse.isnotnull())
			& link
		)
		.groupby(ste_child.item_code, ste_child.s_warehouse)
	).run(as_dict=1)
	return {(d.item_code, d.s_warehouse): flt(d.qty) for d in rows}

def get_disassembly_available_qty(stock_entry_name: str, current_se_name: str | None = None) -> float:
	frappe.has_permission("Stock Entry", "read", doc=stock_entry_name, throw=True)
	se = frappe.db.get_value("Stock Entry", stock_entry_name, ["fg_completed_qty"], as_dict=True)
	if not se:
		return 0.0

	filters = {
		"source_stock_entry": stock_entry_name,
		"purpose": "Disassemble",
		"docstatus": 1,
	}

	if current_se_name:
		filters["name"] = ("!=", current_se_name)

	already_disassembled = flt(frappe.db.get_value("Stock Entry", filters, [{"SUM": "fg_completed_qty"}]))

	return flt(
		flt(se.fg_completed_qty) - already_disassembled,
		frappe.get_precision("Stock Entry", "fg_completed_qty"),
	)

def split_qty_based_on_batch_size(wo_doc, row, qty):
	if not cint(frappe.db.get_value("Operation", row.operation, "create_job_card_based_on_batch_size")):
		row.batch_size = row.get("qty") or wo_doc.qty

	row.job_card_qty = row.batch_size
	if row.batch_size and qty >= row.batch_size:
		qty -= row.batch_size
	elif qty > 0:
		row.job_card_qty = qty
		qty = 0

	get_serial_nos_for_job_card(row, wo_doc)

	return qty
